<script setup lang="ts">
import { ref } from 'vue'
import { useI18n } from 'vue-i18n'
import type { ChartRow } from '@/api/adminDashboard'
import { formatBackendTime } from '@/utils/timezone'
defineProps<{rows?:ChartRow[];loading?:boolean}>();const{t,te}=useI18n();const visible=ref(false);const selected=ref<ChartRow>({});function detail(row:ChartRow){selected.value=row;visible.value=true}function fieldLabel(key:string){const path=`dashboardBI.alertFields.${key}`;return te(path)?t(path):key}
</script><template><el-card class="section-card" shadow="never"><template #header><h3 class="section-title">{{ t('dashboardBI.sections.alerts') }}</h3></template><el-table :data="rows" v-loading="loading" row-key="id" max-height="360"><el-table-column prop="level" :label="t('dashboardBI.alert.level')" width="90"><template #default="{row}"><el-tag :type="row.level==='critical'?'danger':row.level==='high'?'warning':'info'">{{ t(`dashboardBI.values.${row.level}`) }}</el-tag></template></el-table-column><el-table-column prop="alert_type" :label="t('dashboardBI.alert.type')" min-width="180" show-overflow-tooltip/><el-table-column prop="summary" :label="t('dashboardBI.alert.summary')" min-width="260" show-overflow-tooltip/><el-table-column prop="related_provider" :label="t('dashboardBI.alert.related')" min-width="140"><template #default="{row}">{{ row.related_provider || row.related_user || row.related_order || '-' }}</template></el-table-column><el-table-column prop="detected_time" :label="t('dashboardBI.alert.detectedTime')" width="180"><template #default="{row}">{{ formatBackendTime(String(row.detected_time||'')) }}</template></el-table-column><el-table-column prop="status" :label="t('dashboardBI.alert.status')" width="120"/><el-table-column fixed="right" :label="t('common.actions')" width="90"><template #default="{row}"><el-button link type="primary" @click="detail(row)">{{ t('common.detail') }}</el-button></template></el-table-column></el-table><el-dialog v-model="visible" :title="t('dashboardBI.alert.detailTitle')" width="560px"><el-descriptions :column="1" border><el-descriptions-item v-for="(value,key) in selected" :key="key" :label="fieldLabel(String(key))">{{ value ?? '-' }}</el-descriptions-item></el-descriptions></el-dialog></el-card></template>
